package br.univali.pdi; import org.opencv.core.Mat; import org.opencv.imgcodecs.Imgcodecs; public final class ImageIO { private ImageIO(){} public static Mat read(String path){ OpenCvRuntime.ensureLoaded(); Mat m=Imgcodecs.imread(path,Imgcodecs.IMREAD_UNCHANGED); if(m.empty()) throw new IllegalArgumentException("Nao foi possivel abrir a imagem: "+path); return m; } public static void write(String path,Mat image){ OpenCvRuntime.ensureLoaded(); if(image==null||image.empty()) throw new IllegalArgumentException("A imagem de saida esta vazia."); if(!Imgcodecs.imwrite(path,image)) throw new IllegalStateException("Nao foi possivel salvar a imagem: "+path); } }
